const EventEmitter = require("events");

class Element extends EventEmitter {
    constructor(name, parent = null) {
        super();
        this.name = name;
        this.parent = parent;
    }

    addEventListener(type, handler) {
        this.on(type, handler);
    }

    removeEventListener(type, handler) {
        this.off(type, handler);
    }

    dispatchEvent(type, data) {
        const event = {
            type: type,
            target: this,
            currentTarget: this,
            data: data,
            propagationStopped: false,

            stopPropagation() {
                this.propagationStopped = true;
            }
        };

        let current = this;

        while (current !== null) {
            event.currentTarget = current;

            current.emit(type, event);

            if (event.propagationStopped) {
                break;
            }

            current = current.parent;
        }
    }
}

// Create hierarchy
const documentElement = new Element("document");
const form = new Element("form", documentElement);
const button = new Element("button", form);

// Common click handler
function clickHandler(event) {
    console.log(
        `Click handled by ${this.name} | Target: ${event.target.name} | CurrentTarget: ${event.currentTarget.name}`
    );
}

// Attach click listeners
documentElement.addEventListener("click", clickHandler);
form.addEventListener("click", clickHandler);
button.addEventListener("click", clickHandler);

// Scenario A
console.log("\n--- Scenario A: Normal Bubbling ---");
button.dispatchEvent("click", { message: "Button clicked" });

// Scenario B
console.log("\n--- Scenario B: Stop Propagation ---");

function stopHandler(event) {
    console.log(
        `Click handled by ${this.name} | Target: ${event.target.name} | CurrentTarget: ${event.currentTarget.name}`
    );

    event.stopPropagation();
}

form.removeEventListener("click", clickHandler);
form.addEventListener("click", stopHandler);

button.dispatchEvent("click", { message: "Button clicked again" });

// Scenario C
console.log("\n--- Scenario C: Remove Button Listener ---");

button.removeEventListener("click", clickHandler);

button.dispatchEvent("click", { message: "Third click" });

// Keypress event on form
console.log("\n--- Keypress Event ---");

form.addEventListener("keypress", function (event) {
    console.log(
        `Keypress handled by ${this.name} | Key: ${event.data.key}`
    );
});

form.dispatchEvent("keypress", { key: "Enter" });